begin;
set local role service_role;
do $test$
declare r jsonb; other jsonb; i int; first_token text:=repeat('a',64); second_token text:=repeat('c',64);
begin
 r:=public.cq_account_api('signup',jsonb_build_object('email','qa-rollback@example.invalid','password','Temporary-test-only-123','recovery',repeat('b',64),'newToken',first_token));
 assert r ? 'user', 'Signup failed';
 for i in 1..3 loop r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','wrong','newToken',repeat('d',64)));end loop;
 assert (r->>'retryAfter')::int=300,'First lock must be 5 minutes';
 r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','Temporary-test-only-123','newToken',repeat('d',64)));
 assert (r->>'status')::int=429,'A correct password cannot bypass an active lock';
 update cq_private.login_limits set blocked_until=now()-interval '1 second' where key='login:'||encode(extensions.digest('qa-rollback@example.invalid','sha256'),'hex');
 for i in 1..3 loop r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','wrong','newToken',repeat('d',64)));end loop;
 assert (r->>'retryAfter')::int=1200,'Second lock must be 20 minutes';
 update cq_private.login_limits set blocked_until=now()-interval '1 second' where key='login:'||encode(extensions.digest('qa-rollback@example.invalid','sha256'),'hex');
 for i in 1..3 loop r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','wrong','newToken',repeat('d',64)));end loop;
 assert (r->>'retryAfter')::int=4800,'Third lock must be 80 minutes';
 update cq_private.login_limits set blocked_until=now()-interval '1 second' where key='login:'||encode(extensions.digest('qa-rollback@example.invalid','sha256'),'hex');
 r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','Temporary-test-only-123','newToken',repeat('d',64)));
 assert r ? 'user','Correct login after waiting must succeed';
 assert (select stage=0 and failures=0 from cq_private.login_limits where key='login:'||encode(extensions.digest('qa-rollback@example.invalid','sha256'),'hex')),'Successful login resets lockout escalation';
 r:=public.cq_account_api('progress',jsonb_build_object('token',first_token,'progress',jsonb_build_object('version',2,'xp',400),'revision',0));
 assert (r->>'revision')::int=1,'Progress revision must increase';
 r:=public.cq_account_api('progress',jsonb_build_object('token',first_token,'progress',jsonb_build_object('version',2,'xp',20),'revision',0));
 assert (r->>'status')::int=409,'Stale device must not overwrite progress';
 other:=public.cq_account_api('signup',jsonb_build_object('email','qa-second-rollback@example.invalid','password','Another-test-only-123','recovery',repeat('e',64),'newToken',second_token));
 other:=public.cq_account_api('progress',jsonb_build_object('token',second_token));
 assert other->'progress'='null'::jsonb,'Second account must not see first account progress';
 r:=public.cq_account_api('recover',jsonb_build_object('email','qa-rollback@example.invalid','password','Replacement-test-only-123','recovery',repeat('b',64),'newRecovery',repeat('f',64),'newToken',repeat('1',64)));
 assert r ? 'user','Recovery must succeed with saved code';
 r:=public.cq_account_api('progress',jsonb_build_object('token',first_token));
 assert (r->>'status')::int=401,'Recovery must revoke old sessions';
 r:=public.cq_account_api('recover',jsonb_build_object('email','qa-rollback@example.invalid','password','Replacement-test-only-123','recovery',repeat('b',64),'newRecovery',repeat('f',64),'newToken',repeat('2',64)));
 assert (r->>'status')::int=401,'Old recovery code must stop working';
 r:=public.cq_account_api('login',jsonb_build_object('email','qa-rollback@example.invalid','password','Replacement-test-only-123','newToken',repeat('2',64)));
 assert r ? 'user','New password must work';
 r:=public.cq_account_api('progress',jsonb_build_object('token',repeat('2',64)));
 assert (r->'progress'->>'xp')::int=400,'Password recovery preserves saved progress';
 assert not has_table_privilege('anon','cq_private.accounts','select'),'Anonymous table reads must be denied';
 assert not has_function_privilege('anon','public.cq_account_api(text,jsonb)','execute'),'Anonymous RPC access must be denied';
 assert not has_function_privilege('authenticated','public.cq_account_api(text,jsonb)','execute'),'Built-in Auth users must not bypass custom session checks';
end $test$;
rollback;
select 'PASS: account signup, login, 5/20/80-minute escalation, active lock enforcement, successful reset, session revocation, code rotation, account isolation, stale-write rejection and restricted privileges. Test data rolled back.' as verification;
